with unpacked as (select id, customer_id, items, coalesce(ship_to.country, 'UNKNOWN') as country_or_unknown, aggregate(items, cast(0 as double), (acc, x) -> acc + x.qty * x.price, acc -> round(acc, 2)) as cart_value from carts where customer_id is null) select case when cart_value >= 1610 then 'HIGH' else 'LOW' end as cart_value_tier, round(avg(cart_value), 2) as avg_cart_value, count(distinct customer_id) as distinct_customer_ids, count(distinct customer_id) as distinct_customer_ids_2 from unpacked group by cart_value_tier order by cart_value_tier desc;
